mapper.select:
SELECT , c.name AS category_name, u.nickname AS seller_name, u.avatar AS seller_avatar FROM tb_item i LEFT JOIN tb_category c ON c.id = i.category_id LEFT JOIN tb_user u ON u.id = i.seller_id WHERE i.deleted = 0
AND i.status = #{q.status}
AND i.category_id = #{q.categoryId}
AND i.seller_id = #{q.sellerId}
AND (i.title LIKE CONCAT('%', #{q.keyword}, '%') OR i.description LIKE CONCAT('%', #{q.keyword}, '%'))
AND i.price >= #{q.minPrice}
AND i.price <= #{q.maxPrice}
AND i.campus = #{q.campus}
ORDER BY
i.price ASC, i.create_time DESC i.price DESC, i.create_time DESC i.view_count DESC, i.create_time DESC i.create_time DESC
